sh -c 't=$(mktemp -d) || exit 1; echo "#smoke-host 1"; echo "#os-release"; grep -E "^(ID|VERSION_ID|VERSION_CODENAME)=" /etc/os-release; echo "#kernel"; uname -r; echo "#packages dpkg"; dpkg-query -W -f="\${db:Status-Abbrev}\t\${Package}\t\${Version}\t\${Architecture}\t\${source:Package}\t\${source:Version}\n"; echo "#services"; systemctl list-units --type=service --state=running --no-legend --plain 2>/dev/null | cut -d" " -f1 | tee "$t/u"; echo "#service-packages"; ls /proc | awk -v t="$t" "BEGIN { while ((getline l < (t \"/u\")) > 0) r[l] = 1 } /^[0-9]+\$/ { s = \"\"; f = \"/proc/\" \$0 \"/cgroup\"; while ((getline l < f) > 0) if (s == \"\" && l ~ /^[0-9]+:(name=systemd)?:/) for (n = split(l, a, \"/\"); n > 1; n--) if (a[n] ~ /\.service\$/) { s = a[n]; break }; close(f); if (s == \"\" || !(s in r)) next; f = \"/proc/\" \$0 \"/maps\"; if ((k = (getline l < f)) < 0) { b[s] = 1; next }; g[s] = 1; for (; k > 0; k = (getline l < f)) if (match(l, /^[^ ]+ +[^ ]+ +[^ ]+ +[^ ]+ +[^ ]+ +\//)) { p = substr(l, RLENGTH); sub(/ \(deleted\)\$/, \"\", p); m[s \"\t\" p] = 1 }; close(f) } END { for (s in g) if (!(s in b)) print s \"\t\"; for (k in m) { split(k, a, \"\t\"); if (a[1] in b) continue; print k; if (a[2] ~ /^\/usr\/(lib[^\/]*|bin|sbin)\//) print a[1] \"\t\" substr(a[2], 5); else if (a[2] ~ /^\/(lib[^\/]*|bin|sbin)\//) print a[1] \"\t/usr\" a[2] } }" >"$t/o"; cut -f2 "$t/o" | grep "^/" | LC_ALL=C sort -u | tr "\n" "\0" | xargs -0r dpkg -S 2>/dev/null >"$t/s"; awk -F "\t" "FILENAME == ARGV[1] { i = index(\$0, \": \"); if (i && \$0 !~ /^(local )?diversion /) { n = split(substr(\$0, 1, i - 1), a, \", \"); for (j = 1; j <= n; j++) { sub(/:.*/, \"\", a[j]); w[substr(\$0, i + 2)] = w[substr(\$0, i + 2)] \" \" a[j] } }; next } { print \$1 \"\t\"; n = split(w[\$2], a, \" \"); for (j = 1; j <= n; j++) print \$1 \"\t\" a[j] }" "$t/s" "$t/o" | LC_ALL=C sort -u | awk -F "\t" "function e() { if (u != \"\" && n <= 300 && c++ < 200) print u \"\tmaps\t\" l } \$1 != u { e(); u = \$1; l = \"\"; n = 0 } \$2 != \"\" { l = l (n++ ? \" \" : \"\") \$2 } END { e() }"; rm -rf "$t"; echo "#reboot-required"; [ -f /var/run/reboot-required ] && echo yes || echo no' > smoke-host.txt && echo "Saved $(pwd)/smoke-host.txt"
